// Quality control with the EUCAST QC strains: an antibiogram can be marked as a QC strain and its
// zone diameters are compared with the EUCAST target and range. Used by the views and the Excel export
// of both flavours; backend/app/qc.py does the same for the Excel export of the API.
//
// qcTables.json is generated by backend/scripts/eucast_qc_pdf_to_json.py from "Routine and extended
// internal quality control for MIC determination and disk diffusion as recommended by EUCAST"
// (the same file is in backend/seed/qc/).
import type { Antibiogram, Antibiotic, Family, Measurement } from "./api";
import tables from "./qcTables.json";

export type QcUse = "routine" | "inhibitor" | "extended";
export interface QcRange {
  agent: string; disk_content: string; min: number; max: number; use: QcUse;
  target?: string; expected_category?: string;
}
export interface QcStrain { id: string; name: string; genus: string; species: string; ranges: QcRange[] }

export const QC_TABLES = tables as unknown as {
  name: string; version: string; valid_from: string; url: string; citation: string; strains: QcStrain[];
};
export const QC_SOURCE = `${QC_TABLES.name} v ${QC_TABLES.version} (valid from ${QC_TABLES.valid_from})`;
export const QC_STRAINS = QC_TABLES.strains;
const strainById = new Map(QC_STRAINS.map((s) => [s.id, s]));

export const qcStrain = (id: string | null | undefined): QcStrain | undefined => (id ? strainById.get(id) : undefined);

export const USE_LABEL: Record<QcUse, string> = {
  routine: "Routine QC",
  inhibitor: "Inhibitor component of β-lactam-inhibitor combinations",
  extended: "Extended QC (resistance mechanisms)",
};

/** "Cefuroxime iv" and "Cefuroxime oral" are the same disk. */
const agentKey = (name: string, disk: string) => `${name.toLowerCase().replace(/ (iv|oral)$/, "").trim()}|${disk.trim()}`;

export function qcRange(strain: QcStrain | undefined, antibiotic: Pick<Antibiotic, "name" | "disk_content">): QcRange | undefined {
  const key = agentKey(antibiotic.name, antibiotic.disk_content);
  return strain?.ranges.find((r) => agentKey(r.agent, r.disk_content) === key);
}

export type QcStatus = "in" | "low" | "high" | "no-range";
export interface QcResult { range?: QcRange; status: QcStatus }

export function qcResult(strain: QcStrain | undefined, m: Pick<Measurement, "antibiotic" | "diameter_mm">): QcResult {
  const range = qcRange(strain, m.antibiotic);
  if (!range) return { status: "no-range" };
  // Zone diameters are read to the whole millimetre (EUCAST disk diffusion manual).
  const d = Math.round(m.diameter_mm);
  return { range, status: d < range.min ? "low" : d > range.max ? "high" : "in" };
}

export const rangeLabel = (r: QcRange) => (r.min === r.max ? `${r.min}` : `${r.min}–${r.max}`);

export const STATUS_LABEL: Record<QcStatus, string> = {
  in: "In range", low: "Out of range (too small)", high: "Out of range (too large)", "no-range": "No QC range",
};

/** Counts of the QC results of an antibiogram. */
export function qcSummary(a: Antibiogram): { strain?: QcStrain; inRange: number; out: number; noRange: number } {
  const strain = qcStrain(a.qc_strain);
  let inRange = 0, out = 0, noRange = 0;
  for (const p of a.plates) {
    for (const m of p.measurements) {
      const s = qcResult(strain, m).status;
      if (s === "in") inRange++; else if (s === "no-range") noRange++; else out++;
    }
  }
  return { strain, inRange, out, noRange };
}

// Breakpoint group of the organism of each QC strain (names of the bacteria families of the catalogue).
const FAMILY_BY_GENUS: Record<string, string> = {
  Escherichia: "Enterobacteriaceae", Klebsiella: "Enterobacteriaceae", Pseudomonas: "Pseudomonas spp.",
  Staphylococcus: "Staphylococcus spp.", Enterococcus: "Enterococcus spp.", Campylobacter: "Campylobacter jejuni and coli",
  Bacteroides: "Gram-negative anaerobes", Clostridium: "Gram-positive anaerobes except Clostridium difficile",
};
const FAMILY_BY_SPECIES: Record<string, string> = {
  "Streptococcus pneumoniae": "Streptococcus pneumoniae", "Haemophilus influenzae": "Haemophilus influenzae",
};

export function qcFamily(strain: QcStrain, families: Family[]): Family | undefined {
  const name = FAMILY_BY_SPECIES[`${strain.genus} ${strain.species}`] ?? FAMILY_BY_GENUS[strain.genus];
  return families.find((f) => f.name === name);
}
